function sumLast3(values) {
  let total = 0;
  for (let i = values.length - 3; i <= values.length; i++) {
    total = total + values[i];
  }
  return total;
}

console.log(sumLast3([5, 10, 20, 30]), sumLast3([7, 8]), sumLast3([]));

questions.solution:
function sumLast3(values) {
  let total = 0;
  const start = Math.max(0, values.length - 3);
  for (let i = start; i < values.length; i++) {
    total = total + values[i];
  }
  return total;
}

console.log(sumLast3([5, 10, 20, 30]), sumLast3([7, 8]), sumLast3([]));

