function activeCoupons(coupons) {
  for (let i = 0; i < coupons.length; i++) {
    if (coupons[i].expired) coupons.splice(i, 1);
  }
  return coupons;
}

const coupons = [
  { code: "SAVE5", expired: true },
  { code: "SAVE10", expired: true },
  { code: "WELCOME", expired: false },
];
const active = activeCoupons(coupons);
let codes = "";
for (const c of active) codes = codes + c.code + " ";
console.log(codes.trim(), coupons.length);

questions.solution:
function activeCoupons(coupons) {
  const kept = [];
  for (const coupon of coupons) {
    if (!coupon.expired) kept.push(coupon);
  }
  return kept;
}

const coupons = [
  { code: "SAVE5", expired: true },
  { code: "SAVE10", expired: true },
  { code: "WELCOME", expired: false },
];
const active = activeCoupons(coupons);
let codes = "";
for (const c of active) codes = codes + c.code + " ";
console.log(codes.trim(), coupons.length);

