function isPaid(dueNaira, paymentsNaira) {
  let paid = 0;
  for (const p of paymentsNaira) paid = paid + p;
  return paid === dueNaira;
}

console.log(isPaid(0.8, [0.7, 0.1]), isPaid(3.3, [1.1, 2.2]), isPaid(5, [2, 2]));

questions.solution:
function isPaid(dueNaira, paymentsNaira) {
  let paidKobo = 0;
  for (const p of paymentsNaira) paidKobo = paidKobo + Math.round(p * 100);
  return paidKobo === Math.round(dueNaira * 100);
}

console.log(isPaid(0.8, [0.7, 0.1]), isPaid(3.3, [1.1, 2.2]), isPaid(5, [2, 2]));

